EXPORT ZZT_ENCROWS()
BEGIN
  LOCAL R,Z,P,Q,K,V;
  HComplex:=1;
  A:=0;
  IFERR R:=stddev([[0+1,4],[3,8]],[[-1,1],[3,1],[1,1]]); THEN R:="caught"; A:=A+10; END;
  Z:=stddev([[ 0+1, .50 ],[3E0,8],[5,12]],[[-1,1],[3,1]]);
  P:=stddev([[0+1,4],[3,8]],[[-1],[3]]);
  Q:=stddev([[ZZT_LEFT(),4],[3,8]],[[ZZT_RIGHT(),1],[3,1],[1,1]]);
  K:=stddev([[0+1,4],[3,8]],[[-1,1],[3,1]]);
  V:=stddev([0+1,3],[-.5,1.5]);
  L1:={R,Z,P,Q};
  RETURN {{TYPE(R),R,INSTRING(R,CHAR(10))},{TYPE(Z),Z},
          {TYPE(P),P},{TYPE(Q),Q},A,{TYPE(K),STRING(K)},{TYPE(V),ROUND(V,8)}};
END;
ZZT_LEFT()
BEGIN
  A:=A*10+1;
  RETURN 1;
END;
ZZT_RIGHT()
BEGIN
  A:=A*10+2;
  RETURN 1;
END;

EXPORT ZZT_ENCROWS()
BEGIN
  LOCAL R:=L1(1),Z:=L1(2),P:=L1(3),Q:=L1(4);
  RETURN {{TYPE(R),R,INSTRING(R,CHAR(10))},{TYPE(Z),Z},{TYPE(P),P},{TYPE(Q),Q}};
END;

EXPORT ZZT_ENCROWS() BEGIN
LOCAL R,O:={}; LOCAL D:=[[1,4],[3,8]], W:=[[1,1],[1,1],[1,1]]; HComplex:=1;
IFERR R:=stddev( [[ 0 + 1, .50 ], [3E0,8]], [[ - 1, 1], [3,1], [1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[1+(-2+1),4],[3,8]], [[-1,1],[3,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[1E20+1,4],[3,8]], [[-1,1],[3,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[D(1,1),4],[3,8]], [[-1,1],[3,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
RETURN O; END;

EXPORT ZZT_ENCROWS() BEGIN
LOCAL R,O:={}; LOCAL D:=[[1,4],[3,8]], W:=[[1,1],[1,1],[1,1]]; HComplex:=1;
IFERR R:=stddev([[0+1,4],[3,8]],[[-1,1],[3,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1,4],[3,8],[5,12]],[[-1,1],[3,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1,4],[3,8]],[[-1],[3]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1],[3]],[[-1,1],[3,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1,4],[3,8]],[[-.5,1], [.5,1], [1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1,4,6],[3,8,9]],[[-1,1],[3,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[0+1,4],[3,8]],[[1-0,1],[1,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
RETURN O; END;

EXPORT ZZT_ENCROWS() BEGIN
LOCAL R; A:=0;
IFERR R:=stddev([[ZZT_LEFT(),4],[3,8]],[[ZZT_RIGHT(),1],[3,1],[1,1]]); THEN R:="caught"; END;
RETURN {A,TYPE(R),R}; END;
ZZT_LEFT() BEGIN A:=A*10+1; RETURN 1; END;
ZZT_RIGHT() BEGIN A:=A*10+2; RETURN 1; END;

EXPORT ZZT_ENCROWS() BEGIN
LOCAL R; A:=0;
IFERR R:=stddev([[ZZT_LEFT(),4],[3,8],[5,12]],[[ZZT_RIGHT(),1],[3,1]]); THEN R:="caught"; END;
RETURN {A,TYPE(R),R}; END;
ZZT_LEFT() BEGIN A:=A*10+1; RETURN 1; END;
ZZT_RIGHT() BEGIN A:=A*10+2; RETURN 1; END;
